// カート獲得のための最適価格算出ロジック
function calculateOptimalPrice(rivalOffers, minPriceLimit) {
  const lowestRealPrice = Math.min(...rivalOffers.map(o => o.listingPrice - o.points));
  const targetPrice = lowestRealPrice - 1;
  return Math.max(targetPrice, minPriceLimit);
}

